PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <urn:ref:>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?ahuLabel ?ahu ?zone ?zoneLabel WHERE {
  ?ahu a brick:AirHandlingUnit .
  OPTIONAL { ?ahu brick:feeds ?zone }
  OPTIONAL { ?ahu rdfs:label ?ahuLabel }
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?s ?cls ?label WHERE {
  ?s a ?cls ; rdfs:label ?label .
  FILTER (regex(str(?label),"AHU02","i"))
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?s ?cls ?label WHERE {
  ?s a ?cls .
  FILTER (regex(str(?s),"AHU","i") || regex(str(?s),"ahu02","i"))
  OPTIONAL { ?s rdfs:label ?label }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?ahu ?zone ?zoneLabel ?pstat WHERE {
  ?ahu a brick:Air_Handling_Unit .
  FILTER (regex(str(?ahu),"AHU02","i"))
  ?ahu brick:feeds ?zone .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
